// ── source: vcx/tests/store_core_umbrella_test.v ──
// ── source: vcx/tests/store_concurrent_handle_test.v ──
// store_concurrent_handle_test.v — #74 Defect 2: concurrent access to a single
// shared cx-stdlib/store handle under `[par]` must NOT crash the process. Before
// the fix, `[par]` put-doc / get-doc over one handle raced the docs/aliases maps
// (and the per-op cap state) and segfaulted nondeterministically (observed exit
// 139 / signal 11 ~1-in-10 runs). The fix serializes per-store ops behind a
// non-blocking try_lock: a contending worker gets a clean E_STORE_HANDLE_RACE
// (CXER1140) value instead of a crash, so the program always completes cleanly.
//
// A data race is nondeterministic, so this asserts the invariant the prompt
// specifies: run the repro MANY times and require every run to exit cleanly
// (never a signal kill). Handle-race errors are values the program discards, so
// the top-level reduce still returns its count → exit 0 on every run.

fn cx_bin_store() string {
	return testenv.cx_bin()
}

const par_put_repro = "[?lib 'cx-stdlib/store']
[?let [= \$s [\$store:open \"mem://\"]]
  [?reduce [\$range 1 5000] [using [?fn (\$a \$i)
    [?let [= \$h [\$store:put-doc \$s [doc [v \$i]]]] [+ \$a 1]]]] [init 0] [par]]]
"

const par_read_repro = "[?lib 'cx-stdlib/store']
[?let [= \$s [\$store:open \"mem://\"]]
  [= \$h0 [\$store:put-doc \$s [doc [v 1]]]]
  [?reduce [\$range 1 5000] [using [?fn (\$a \$i)
    [?let [= \$d [\$store:get-doc \$s \$h0]] [+ \$a 1]]]] [init 0] [par]]]
"

// run the program `runs` times; assert no run dies on a signal (exit >= 128).
fn assert_no_crash(label string, src string, runs int) {
	prog := os.join_path(os.temp_dir(), 'cx_store74_${label}_${os.getpid()}.cx')
	os.write_file(prog, src) or { panic('write: ${err}') }
	defer { os.rm(prog) or {} }
	for i in 0 .. runs {
		r := os.execute('${cx_bin_store()} --allow-all ${prog}')
		// A signal-killed child surfaces as exit_code >= 128 (128 + signum),
		// e.g. 139 for SIGSEGV. The pre-fix race crashed here.
		assert r.exit_code < 128, '${label} run ${i}: process killed by signal (exit ${r.exit_code}) — concurrent shared-handle access crashed:\n${r.output}'
		// Clean completion: handle-race errors are discarded values, so the
		// top-level reduce returns its count and the process exits 0.
		assert r.exit_code == 0, '${label} run ${i}: non-clean exit ${r.exit_code}:\n${r.output}'
	}
}

// #847: the BYTES lane (store put/get) must navigate identically to the
// in-memory value — `*` on the child axis included. The runtime lane holds a
// __cx_seq__ marker element for a bare sequence-valued body; the decoded lane
// used to hold a bare SequenceNode the wildcard silently dropped, so a
// renderer walking /* emitted an empty table after the wire that was full
// before it. Pinned end-to-end through the real binary.
const wildcard_parity_847 = "[?lib 'cx-stdlib/store']
[?let [= \$t [c [?for [in \$x (\"A\",\"B\")] [yield [x \$x]]]]]
  [= \$s [\$store:open \"mem://\"]]
  [= \$h [\$store:put-doc \$s \$t]]
  [= \$g [\$store:get-doc \$s \$h]]
  [list [\$count \$t/*] [\$count \$g/*] [\$count \$g/*/x]
        [= [\$cx:hash \$t] [\$cx:hash \$g]]]]
"

fn test_wildcard_child_axis_store_roundtrip_847() {
	prog := os.join_path(os.temp_dir(), 'cx_847_parity_${os.getpid()}.cx')
	os.write_file(prog, wildcard_parity_847) or { panic('write: ${err}') }
	defer { os.rm(prog) or {} }
	r := os.execute('${cx_bin_store()} --allow-all ${prog}')
	assert r.exit_code == 0, '#847 store parity program failed (exit ${r.exit_code}):\n${r.output}'
	// R-A1 (2026-08-25): [?for] in element content contributes real
	// children, so /* is 2 on both sides of the bytes lane and /*/x is 0
	// (no x under an x) — parity + hash equality, the pin's actual point,
	// hold at the ruled values.
	assert r.output.contains('[list 2 2 0 true]'), '#847 bytes-lane parity broke: ${r.output}'
}

fn test_par_shared_handle_writes_never_crash() {
	assert_no_crash('write', par_put_repro, 60)
}

fn test_par_shared_handle_reads_never_crash() {
	assert_no_crash('read', par_read_repro, 40)
}

// Sequential use is unaffected by the guard (no deadlock, correct result).
fn test_sequential_store_unaffected() {
	src := "[?lib 'cx-stdlib/store']
[?let [= \$s [\$store:open \"mem://\"]]
  [= \$h [\$store:put-doc \$s [doc [v 7]]]]
  [= \$_ [\$store:set-alias \$s \"k7\" \$h]]
  [\$store:get-doc \$s [\$store:get-alias \$s \"k7\"]]]
"
	prog := os.join_path(os.temp_dir(), 'cx_store74_seq_${os.getpid()}.cx')
	os.write_file(prog, src) or { panic('write: ${err}') }
	defer { os.rm(prog) or {} }
	r := os.execute('${cx_bin_store()} --allow-all ${prog}')
	assert r.exit_code == 0, 'sequential store errored: ${r.output}'
	assert r.output.contains('[doc [v 7]]'), 'sequential round-trip wrong: ${r.output}'
	_ := time.now()
}

// ── source: vcx/tests/store_dir_sync_test.v ──
// store_dir_sync_test.v — BEHAVIORAL test for the directory<->store ingest/sync
// recipe (examples/cxstore/dir-sync, #128). It runs the SHIPPED ingest.cx +
// materialize.cx against the example's sample/ tree and asserts:
//   1. ingest stores the .cxd docs (content-addressed) and names them by path;
//   2. re-running ingest is idempotent (identical output → same hashes/aliases);
//   3. materialize round-trips each doc back to ./restored under its named path,
//      canonical-equal to the source.
// Black-box: spawns the prebuilt vcx/target/cx (run `make build-vcx` first), in
// the example directory. Generated out-store/ and restored/ are cleaned up.

fn dirsync_cx_binary() string {
	return testenv.cx_bin()
}

fn dirsync_example_dir() string {
	abs := os.real_path('examples/cxstore/dir-sync')
	if !os.is_dir(abs) {
		panic('example dir not found at ${abs}')
	}
	return abs
}

fn dirsync_clean(ex string) {
	os.rmdir_all(os.join_path(ex, 'out-store')) or {}
	os.rmdir_all(os.join_path(ex, 'restored')) or {}
}

fn test_dir_sync_ingest_materialize_roundtrip() {
	cx_bin_path := dirsync_cx_binary()
	ex := dirsync_example_dir()
	dirsync_clean(ex)
	defer {
		dirsync_clean(ex)
	}

	// (1) ingest: stores the sample docs, named by path.
	r1 := os.execute('cd "${ex}" && "${cx_bin_path}" --allow-all ingest.cx')
	assert r1.exit_code == 0, 'ingest failed: ${r1.output}'
	assert r1.output.contains("path='sample/notes/hello.cxd'"), 'hello.cxd not ingested: ${r1.output}'
	assert r1.output.contains('hash='), 'no content hash emitted: ${r1.output}'
	// (1b) F1' (RULED 2026-08-08): the .cx CODE file is an OPAQUE document —
	// ingested via put-blob (identity = hash of the raw bytes), retrievable by
	// its path alias via get-blob, BYTE-EXACT. This is the acceptance fixture
	// the F1' ruling names: the def's concrete syntax (single-quoted literal,
	// spacing) survives storage untouched.
	assert r1.output.contains("kind=code path='sample/code/greet.cx'"), 'greet.cx not ingested as code: ${r1.output}'
	assert !r1.output.contains('CXER'), 'ingest emitted an error: ${r1.output}'
	// retrieve the code bytes by path alias: get-alias -> raw-hash -> get-blob.
	probe := '[?lib \'cx-stdlib/store\' :as store] [?let [= \$c [\$store:open "file://./out-store"]] [\$store:get-blob \$c [\$store:get-alias \$c "sample/code/greet.cx"]]]'
	pp := os.join_path(ex, 'getblob_probe.cx')
	os.write_file(pp, probe) or { panic('write probe: ${err}') }
	g := os.execute('cd "${ex}" && "${cx_bin_path}" --allow-all getblob_probe.cx')
	os.rm(pp) or {}
	src_bytes := os.read_file(os.join_path(ex, 'sample/code/greet.cx')) or {
		panic('sample greet.cx missing: ${err}')
	}
	assert g.output.contains(src_bytes.trim_space()), 'code bytes not byte-exact via get-blob: ${g.output}'
	// the cxpack store persisted to disk. #129-B persists incrementally, so a
	// small ingest writes segment packs (store-NNNN.cxpack) + the append-only
	// manifest; the single store.cxpack only appears after a compaction. Assert
	// the layout-agnostic invariant: a manifest plus at least one pack file.
	store_dir := os.join_path(ex, 'out-store')
	assert os.exists(os.join_path(store_dir, '.cxpack-manifest')), 'store manifest not persisted'
	mut pack_files := 0
	for e in os.ls(store_dir) or { []string{} } {
		if e.ends_with('.cxpack') {
			pack_files++
		}
	}
	assert pack_files > 0, 'no cxpack pack file persisted in ${store_dir}'

	// (2) idempotent: a second ingest of the unchanged tree yields identical
	// output (same hashes + aliases — re-put is a content-addressed no-op).
	r2 := os.execute('cd "${ex}" && "${cx_bin_path}" --allow-all ingest.cx')
	assert r2.exit_code == 0, 'second ingest failed: ${r2.output}'
	assert r2.output == r1.output, 'ingest not idempotent:\n--- run1 ---\n${r1.output}\n--- run2 ---\n${r2.output}'

	// (3) materialize: write the store back out, recreating the named tree.
	m := os.execute('cd "${ex}" && "${cx_bin_path}" --allow-all materialize.cx')
	assert m.exit_code == 0, 'materialize failed: ${m.output}'
	restored := os.read_file(os.join_path(ex, 'restored/sample/notes/hello.cxd')) or {
		panic('restored hello.cxd missing: ${err}')
	}
	// canonical round-trip: same content + structure (store re-emits canonical form).
	assert restored.contains('note id=hello'), 'restored doc not canonical note: ${restored}'
	assert restored.contains('first note'), 'restored doc lost body: ${restored}'
	// a nested-dir doc round-trips too (tree structure preserved).
	assert os.exists(os.join_path(ex, 'restored/sample/archive/old.cxd')), 'nested doc not restored'
	// (3b) F1' acceptance: the materialized CODE file is BYTE-IDENTICAL to the
	// source — the whole point of the opaque surface (a structured-path detour
	// would canonicalize the quoting and fail this).
	restored_code := os.read_file(os.join_path(ex, 'restored/sample/code/greet.cx')) or {
		panic('restored greet.cx missing: ${err}')
	}
	assert restored_code == src_bytes, 'restored code not byte-identical:\n--- source ---\n${src_bytes}\n--- restored ---\n${restored_code}'
}

// ── source: vcx/tests/store_drain_readiness_test.v ──
// store_drain_readiness_test.v — #233: readiness probes THROUGH graceful drain.
// Pre-#233, the first SIGTERM closed the listener at once, so a load-balancer
// readiness probe got connection-refused and never observed the drain state. Now
// the daemon keeps the listener open for the drain grace ([timeouts drain-ms]):
// on signal it flips readiness false, still answers /ready ([accepting false]) and
// /health, refuses data ops with 503, then closes and drains after the grace.
//
// This spawns `cx store-serve`, sends SIGTERM, and — WITHIN the grace window —
// asserts /ready connects and reports accepting=false (not connection-refused) and
// a data op returns 503. Then it confirms the daemon exits after the grace.

fn dr_cx_binary() string {
	return testenv.cx_bin()
}

fn dr_pick_port() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	return 26900 + int(salt)
}

fn test_drain_readiness_probe_during_grace() {
	if os.execute('command -v curl').exit_code != 0 {
		eprintln('SKIP: curl not available for drain-readiness test')
		return
	}
	port := dr_pick_port()
	dir := os.join_path(os.temp_dir(), 'cx_drain_${port}')
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	cfg := os.join_path(dir, 'svc.cx')
	// generous 4s grace so the probe fires comfortably inside the window.
	os.write_file(cfg, '[cxstore-service [bind addr="127.0.0.1:${port}"] [timeouts drain-ms=4000] [stores [store name="t" url="mem://"]]]') or {
		panic('write cfg: ${err}')
	}
	srv_out := os.join_path(dir, 'srv.out')
	// The net scope IS enforced and stays; the read scope was NOT (#1059) —
	// it now refuses at startup, so the read grant is spelled bare.
	allow := '--allow-net=127.0.0.1:${port} --allow-read'
	pid_s := os.execute('${dr_cx_binary()} store-serve ${allow} --config ${cfg} >${srv_out} 2>&1 & echo \$!')
	if pid_s.exit_code != 0 {
		eprintln('SKIP: could not spawn cx store-serve')
		return
	}
	pid := pid_s.output.trim_space().int()
	mut killed := false
	defer {
		if !killed {
			os.execute('kill ${pid} 2>/dev/null')
		}
	}
	time.sleep(900 * time.millisecond) // let it bind + mark ready

	// Sanity: before drain, /ready is accepting=true.
	pre := os.execute('curl -s --max-time 2 http://127.0.0.1:${port}/cx-store/v1/ready')
	assert pre.output.contains('[accepting true]'), 'before drain /ready must be accepting=true; got: ${pre.output} | srv: ${os.read_file(srv_out) or {
		''
	}}'

	// Send the FIRST SIGTERM → graceful drain begins; listener stays open for grace.
	os.execute('kill -TERM ${pid}')
	killed = true
	time.sleep(400 * time.millisecond) // inside the 4s grace window

	// #233 core: the readiness probe still CONNECTS and observes the draining state
	// (accepting=false), rather than connection-refused.
	ready := os.execute('curl -s --max-time 2 http://127.0.0.1:${port}/cx-store/v1/ready')
	srv_log := os.read_file(srv_out) or { '' }
	assert ready.exit_code == 0, 'readiness probe during drain must connect (not refused) (#233); curl exit ${ready.exit_code}; srv: ${srv_log}'
	assert ready.output.contains('[accepting false]'), 'during drain /ready must report accepting=false; got: ${ready.output}; srv: ${srv_log}'

	// (The data-op-during-drain → 503 refusal is a data-plane concern; the
	// data plane is the gRPC edge / XSP profile now, not raw HTTP — S3/G3a —
	// so it is pinned hermetically on the profile path by
	// store_service_test.v::test_dispatch_data_op_refused_while_draining, not
	// probed over curl here. This live test's #233 subject is the readiness
	// probe surviving the drain grace, asserted above.)

	// After the grace elapses the daemon exits: the listener closes and the probe is
	// refused (process gone).
	time.sleep(4500 * time.millisecond)
	gone := os.execute('curl -s --max-time 2 http://127.0.0.1:${port}/cx-store/v1/ready')
	assert gone.exit_code != 0, 'after the drain grace the daemon must have exited (probe should now fail); got: ${gone.output}'
}

// ── source: vcx/tests/store_file_append_log_test.v ──
// store_file_append_log_test.v — #74 Defect 1: the file:// backend persists via
// an APPEND-ONLY log (one record per mutation) instead of rewriting the entire
// index on every put-doc/set-alias (the O(n) per-op → O(n^2)-total cost that
// made file:// unusable past a few thousand keys). These tests pin the
// behavioral contract that makes the append log safe:
//   1. the log replays identically across a reopen (separate process),
//   2. alias updates are last-write-wins and the log COMPACTS (does not grow
//      unboundedly with redundant records),
//   3. many keyed writes reopen with the full set intact (and complete fast —
//      a soft tripwire against an O(n^2) regression).

fn cx_bin_sfa() string {
	return testenv.cx_bin()
}

fn run_prog(src string) os.Result {
	f := os.join_path(os.temp_dir(), 'cx_sfa_${os.getpid()}_${src.len}.cx')
	os.write_file(f, src) or { panic('write: ${err}') }
	defer { os.rm(f) or {} }
	return os.execute('${cx_bin_sfa()} --allow-all ${f}')
}

fn store_dir(label string) string {
	d := os.join_path(os.temp_dir(), 'cx_sfa_store_${label}_${os.getpid()}')
	os.rmdir_all(d) or {}
	return d
}

// 1. The append log replays across a reopen in a SEPARATE process.
fn test_append_log_roundtrips_across_reopen() {
	dir := store_dir('roundtrip')
	defer { os.rmdir_all(dir) or {} }
	w := run_prog("[?lib 'cx-stdlib/store']
[?let [= \$s [\$store:open \"document+file://${dir}\"]]
  [?let [= \$h1 [\$store:put-doc \$s [doc [v 1]]]]
   [?let [= \$h2 [\$store:put-doc \$s [doc [v 2]]]]
    [?let [= \$_a [\$store:set-alias \$s \"one\" \$h1]]
     [?let [= \$_b [\$store:set-alias \$s \"two\" \$h2]] :wrote]]]]]
")
	assert w.exit_code == 0, 'write failed: ${w.output}'

	// The fetched documents are ELEMENTS, so they ride in child position —
	// attributes are strictly scalar (code.md §6.4.1; #466/#268 ruling).
	r := run_prog("[?lib 'cx-stdlib/store']
[?let [= \$s [\$store:open \"document+file://${dir}\"]]
  [results
    [one [\$store:get-doc \$s [\$store:get-alias \$s \"one\"]]]
    [two [\$store:get-doc \$s [\$store:get-alias \$s \"two\"]]]
    ndocs=[\$count [\$store:list-docs \$s]]]]
")
	assert r.exit_code == 0, 'reopen read failed: ${r.output}'
	assert r.output.contains('[one [doc [v 1]]]'), 'alias one lost across reopen: ${r.output}'
	assert r.output.contains('[two [doc [v 2]]]'), 'alias two lost across reopen: ${r.output}'
	assert r.output.contains('ndocs=2'), 'doc count wrong after reopen: ${r.output}'
}

// 2. Repeated alias updates are last-write-wins after reopen, and the on-disk
//    log COMPACTS — its size stays bounded, not ~one-record-per-update.
fn test_alias_updates_last_write_wins_and_compact() {
	dir := store_dir('compact')
	defer { os.rmdir_all(dir) or {} }
	w := run_prog("[?lib 'cx-stdlib/store']
[?let [= \$s [\$store:open \"document+file://${dir}\"]]
  [?let [= \$h1 [\$store:put-doc \$s [doc [n 1]]]]
   [?let [= \$h2 [\$store:put-doc \$s [doc [n 2]]]]
    [?reduce [\$range 1 500] [using [?fn (\$a \$i)
      [?let [= \$_ [\$store:set-alias \$s \"k\" [?if [> \$i 250] [then \$h2] [else \$h1]]]] [+ \$a 1]]]] [init 0]]]]]
")
	assert w.exit_code == 0, 'update run failed: ${w.output}'

	// Element-valued field in child position (attrs are scalar-only, §6.4.1).
	r := run_prog("[?lib 'cx-stdlib/store']
[?let [= \$s [\$store:open \"document+file://${dir}\"]]
  [final [k [\$store:get-doc \$s [\$store:get-alias \$s \"k\"]]] naliases=[\$count [\$store:list-aliases \$s]]]]
")
	assert r.exit_code == 0, 'reopen after updates failed: ${r.output}'
	assert r.output.contains('[k [doc [n 2]]]'), 'alias update not last-write-wins: ${r.output}'
	assert r.output.contains('naliases=1'), 'expected exactly 1 alias: ${r.output}'

	// Compaction guard: 500 updates to one alias must NOT leave 500 records on
	// disk. A compacted index holds ~2 docs + 1 alias (a few hundred bytes);
	// an uncompacted append log would be many KB. Generous ceiling.
	idx := os.join_path(dir, '.cxstore-index')
	assert os.is_file(idx), 'index file missing: ${idx}'
	sz := os.file_size(idx)
	assert sz < 4096, 'append log did not compact — index is ${sz} bytes after 500 alias updates'
}

// 3. Many unique keyed writes reopen with the full set intact, and complete
//    promptly — a soft tripwire against a return to the O(n^2) full-rewrite.
fn test_many_keyed_writes_reopen_intact() {
	dir := store_dir('scale')
	defer { os.rmdir_all(dir) or {} }
	sw := time.now()
	w := run_prog("[?lib 'cx-stdlib/store']
[?let [= \$s [\$store:open \"document+file://${dir}\"]]
  [?reduce [\$range 1 8000] [using [?fn (\$a \$i)
    [?let [= \$h [\$store:put-doc \$s [doc [v \$i]]]]
      [?let [= \$x [\$store:set-alias \$s [?str \"k{\$i}\"] \$h]] [+ \$a 1]]]]] [init 0]]]
")
	elapsed_ms := f64(time.now() - sw) / f64(time.millisecond)
	assert w.exit_code == 0, '8000 keyed writes failed: ${w.output}'
	// This is the fail-before/pass-after guard for the append-log fix. With the
	// old full-index-rewrite-per-op (O(n^2)) 8000 keyed writes did not complete
	// in tens of seconds (the issue reported >120s); the append log makes it
	// O(n) (sub-second). 30s is a catastrophic-regression tripwire with a huge
	// margin over the linear time even under heavy parallel CI load — not a perf
	// benchmark.
	assert elapsed_ms < 30_000.0, '8000 keyed writes took ${elapsed_ms}ms — O(n^2) full-index rewrite regression (append log broken?)'

	r := run_prog("[?lib 'cx-stdlib/store']
[?let [= \$s [\$store:open \"document+file://${dir}\"]]
  [n ndocs=[\$count [\$store:list-docs \$s]] naliases=[\$count [\$store:list-aliases \$s]]]]
")
	assert r.exit_code == 0, 'reopen after scale write failed: ${r.output}'
	assert r.output.contains('ndocs=8000'), 'not all docs persisted/replayed: ${r.output}'
	assert r.output.contains('naliases=8000'), 'not all aliases persisted/replayed: ${r.output}'
}

// ── source: vcx/tests/store_modify_predicate_test.v ──
// store_modify_predicate_test.v — #141. `$store:modify-doc` `select` must honor
// CXPath step predicates (canonical prefix form `[= $_@attr 'v']`, #110), not
// just bare element-name steps, so a keyed collection element can be targeted
// for update or eviction. Before the fix, every predicate form was a silent
// no-op (the whole predicate string was used as the element name and never
// matched). These tests spawn the real cx binary and pin the green behavior;
// they were RED prior to the store_elem_matches_predicates fix in
// stdlib_store.v.

fn mp_cx() string {
	return testenv.cx_bin()
}

fn mp_run(prog string) os.Result {
	p := os.join_path(os.temp_dir(), 'cx_mp_${os.getpid()}_${prog.len}.cx')
	os.write_file(p, prog) or { panic('write ${p}: ${err}') }
	defer {
		os.rm(p) or {}
	}
	return os.execute('"${mp_cx()}" --allow-all "${p}"')
}

const seed_two = "[?lib 'cx-stdlib/store' :as store] [?let [= \$s [\$store:open \"mem://\"]] " +
	"[?let [= \$h [\$store:put-doc \$s [targets [t mmsi=\"1\" sog=\"0\"] [t mmsi=\"2\" sog=\"0\"]]]] "

// remove by key: only the matched element is deleted.
fn test_remove_by_predicate_key() {
	prog := seed_two +
		"[?let [= \$h2 [\$store:modify-doc \$s \$h [remove select=\"//t[= \$_@mmsi '1']\"]]] " +
		"[\$cx:emit [\$store:get-doc \$s \$h2]]]]]"
	r := mp_run(prog)
	assert r.exit_code == 0, 'remove-by-key failed: ${r.output}'
	assert !r.output.contains("mmsi='1'"), 'keyed target NOT removed: ${r.output}'
	assert r.output.contains("mmsi='2'"), 'non-matching sibling wrongly removed: ${r.output}'
}

// set-attr by key: only the matched element's attribute changes.
fn test_set_attr_by_predicate_key() {
